// Database connection. The whole project uses this single PrismaClient.
// Creating a new client in every file needlessly multiplies the connection pool, so don't.
//
// Prisma 7 notes (why it looks like this):
//  - The client is generated by `npm run db:generate` into generated/prisma as TypeScript
//    (generator setting in schema.prisma: the .mts extension means "always an ES module").
//  - This project is CommonJS, so the ES module is loaded with a dynamic import() instead of
//    require(). That is why creating the client is async.
//  - Prisma 7 connects to the database through a "driver adapter" (PrismaPg + pg), not its own
//    engine.
//  - Node 22.18+ is required: Node's built-in "type stripping" runs the .mts files.
const { PrismaPg } = require('@prisma/adapter-pg');

async function createPrismaClient({ databaseUrl, ssl = false }) {
  if (!databaseUrl) {
    throw new Error('databaseUrl is required to create the Prisma client');
  }

  let PrismaClient;
  try {
    ({ PrismaClient } = await import('../../generated/prisma/client.mts'));
  } catch (err) {
    if (err && err.code === 'ERR_MODULE_NOT_FOUND') {
      throw new Error('Prisma client is not generated yet. Run: npm run db:generate');
    }
    throw err;
  }

  // The Supabase connection pooler may require SSL. If the app cannot connect,
  // add DATABASE_SSL=true to .env.
  const adapter = new PrismaPg({
    connectionString: databaseUrl,
    ...(ssl ? { ssl: { rejectUnauthorized: false } } : {}),
  });

  return new PrismaClient({ adapter });
}

module.exports = { createPrismaClient };
